import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, time, mix, smoothstep, vec2, uniform, texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  const colors = config.intent?.visualSpec?.colors ?? {};
  const ink = new Color(colors.ink ?? '#16161d');
  const paper = new Color(colors.paper ?? '#e8ecf2');
  const accent = new Color(colors.accent ?? '#ff2a38');
  const surface = new Color(colors.surface ?? '#0b0b10');

  const group = new Group();
  const inner = new Group();
  group.add(inner);

  // Card dimensions from atlas aspect (512x320 = 1.6:1)
  const cardW = 2.4;
  const cardH = 1.5;

  const geo = new PlaneGeometry(cardW, cardH, 48, 32);
  const mat = new MeshBasicNodeMaterial();
  mat.transparent = true;

  // Uniforms
  const inkU = uniform(ink);
  const paperU = uniform(paper);
  const accentU = uniform(accent);
  const surfaceU = uniform(surface);
  const texU = uniform(null);

  // Load brushed metal texture
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    if (ctx.THREE.SRGBColorSpace) tex.colorSpace = ctx.THREE.SRGBColorSpace;
    texU.value = tex;
  });

  const uvNode = uv();
  const t = time;

  // Subtle film grain
  const grain = uvNode
    .mul(vec2(900.0, 560.0))
    .add(vec2(t.mul(41.0), t.mul(29.0)))
    .dot(vec2(12.989, 78.233))
    .sin()
    .mul(43758.5453)
    .fract();
  const grainVal = grain.sub(0.5).mul(0.03);

  // Brushed metal texture sample
  const metalTex = texture(texU, uvNode);

  // Engineered vertical gradient: surface (top) -> ink (bottom)
  const gradF = smoothstep(0.0, 1.0, uvNode.y);
  const gradient = mix(surfaceU, inkU, gradF);

  // Metal tint from texture luminance
  const metalLum = metalTex.r.mul(0.35).add(0.3);
  const metalTint = mix(inkU, paperU, metalLum.mul(0.5));

  // Blend gradient with metal
  const baseColor = mix(gradient, metalTint, 0.4);

  // Accent edge strip at top
  const accentEdge = smoothstep(0.94, 1.0, uvNode.y).mul(0.12);
  const withAccent = baseColor.add(accentU.mul(accentEdge));

  // Add grain
  const withGrain = withAccent.add(grainVal);

  // Frame border — darker edge ring
  const ft = 0.02;
  const fx = smoothstep(0.0, ft, uvNode.x).mul(
    smoothstep(0.0, ft, uvNode.x.oneMinus())
  );
  const fy = smoothstep(0.0, ft, uvNode.y).mul(
    smoothstep(0.0, ft, uvNode.y.oneMinus())
  );
  const frameMask = fx.mul(fy);
  const borderColor = mix(inkU, surfaceU, 0.3);
  const finalColor = mix(borderColor, withGrain, frameMask);

  mat.colorNode = finalColor;

  const mesh = new Mesh(geo, mat);
  inner.add(mesh);

  // Entrance: rise-in + weighted-settle
  inner.position.y = 0.4;
  mat.opacity = 0;
  mesh.scale.set(0.96, 0.96, 0.96);

  const tl = gsap.timeline();
  tl.to(inner.position, { y: 0, duration: 0.7, ease: 'power3.out' });
  tl.to(mat, { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0);
  tl.to(mesh.scale, { x: 1.04, y: 1.04, duration: 0.5, ease: 'power2.out' }, 0.55);
  tl.to(mesh.scale, { x: 1.0, y: 1.0, duration: 0.9, ease: 'power4.out' }, 1.0);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    tl.kill();
    geo.dispose();
    mat.dispose();
  };

  return group;
}
